import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

public final class AuthorizationProbe {
    public static void main(String[] args) {
        String snapshot = args[0];
        Map<String, Document> documentsById = Map.of(
                "own", new Document("own", "tenant-a", "own payload"),
                "foreign", new Document("foreign", "tenant-b", "foreign payload"));
        Components components = new Components(documentsById::get);
        User user = new User("tenant-a");
        InteractiveDownload interactive = new InteractiveDownload(components);
        ScheduledExportJob scheduled = new ScheduledExportJob(components);

        expect(snapshot, "interactive own tenant", "own payload", () -> interactive.download(user, "own"));
        expect(snapshot, "scheduled own tenant", List.of("own payload"), () -> scheduled.run(user, List.of("own")));
        expect(snapshot, "interactive other tenant", "Forbidden", () -> interactive.download(user, "foreign"));
        expect(snapshot, "scheduled other tenant",
                snapshot.equals("before") ? "Forbidden" : List.of("foreign payload"),
                () -> scheduled.run(user, List.of("foreign")));
    }

    private static void expect(String snapshot, String label, Object expected, Supplier<?> action) {
        Object actual;
        try {
            actual = action.get();
        } catch (Forbidden denied) {
            actual = "Forbidden";
        }
        System.out.println(snapshot + " | " + label + " | " + actual);
        if (!expected.equals(actual)) {
            throw new AssertionError(label + ": expected " + expected + ", got " + actual);
        }
    }
}

