import java.util.List;
import java.util.Map;

final class ReviewChecks {
    private static int passed;

    public static void main(String[] args) {
        Map<String, Document> data = Map.of(
            "a", new Document("a", "tenant-a", "own payload"),
            "b", new Document("b", "tenant-b", "foreign payload"));
        Documents documents = data::get;
        Components components = new Components(documents);
        User user = new User("tenant-a");
        InteractiveDownload interactive = new InteractiveDownload(components);
        ScheduledExportJob scheduled = new ScheduledExportJob(components);

        expectEqual("interactive own tenant", "own payload", interactive.download(user, "a"));
        expectForbidden("interactive foreign tenant", () -> interactive.download(user, "b"));
        expectEqual("scheduled own tenant", List.of("own payload"), scheduled.run(user, List.of("a")));
        expectForbidden("scheduled foreign tenant", () -> scheduled.run(user, List.of("b")));
        expectForbidden("scheduled mixed tenants", () -> scheduled.run(user, List.of("a", "b")));
        System.out.println("PASS: " + passed + " checks");
    }

    private static void expectEqual(String name, Object expected, Object actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError(name + ": expected " + expected + ", got " + actual);
        }
        passed++;
        System.out.println("PASS: " + name);
    }

    private static void expectForbidden(String name, Runnable action) {
        try {
            action.run();
        } catch (Forbidden expected) {
            passed++;
            System.out.println("PASS: " + name);
            return;
        }
        throw new AssertionError(name + ": expected Forbidden");
    }
}

