final class ExportReviewCheck {
    private static int passed;
    private static int failed;

    public static void main(String[] args) {
        Map<String, Document> documents = Map.of(
                "own", new Document("own", "tenant-a", "own payload"),
                "foreign", new Document("foreign", "tenant-b", "foreign payload"));
        Components components = new Components(documents::get);
        User caller = new User("tenant-a");
        InteractiveDownload interactive = new InteractiveDownload(components);
        ScheduledExportJob scheduled = new ScheduledExportJob(components);

        expectValue("interactive own document", "own payload",
                () -> interactive.download(caller, "own"));
        expectForbidden("interactive foreign document",
                () -> interactive.download(caller, "foreign"));
        expectValue("scheduled own document", List.of("own payload"),
                () -> scheduled.run(caller, List.of("own")));
        expectForbidden("scheduled foreign document",
                () -> scheduled.run(caller, List.of("foreign")));
        expectForbidden("scheduled mixed-tenant documents",
                () -> scheduled.run(caller, List.of("own", "foreign")));
        expectValue("scheduled empty list", List.of(),
                () -> scheduled.run(caller, List.of()));

        System.out.printf("CHECKS: %d passed, %d failed%n", passed, failed);
        if (failed != 0) System.exit(1);
    }

    private static void expectValue(String name, Object expected, Supplier<?> operation) {
        try {
            Object actual = operation.get();
            if (!Objects.equals(expected, actual)) {
                fail(name, "expected " + expected + ", received " + actual);
                return;
            }
            pass(name);
        } catch (RuntimeException exception) {
            fail(name, "unexpected " + exception.getClass().getSimpleName());
        }
    }

    private static void expectForbidden(String name, Supplier<?> operation) {
        try {
            Object actual = operation.get();
            fail(name, "expected Forbidden, returned " + actual);
        } catch (Forbidden expected) {
            pass(name);
        } catch (RuntimeException exception) {
            fail(name, "expected Forbidden, received " + exception.getClass().getSimpleName());
        }
    }

    private static void pass(String name) {
        passed++;
        System.out.println("PASS " + name);
    }

    private static void fail(String name, String detail) {
        failed++;
        System.out.println("FAIL " + name + ": " + detail);
    }
}

