import java.util.List;
import java.util.Map;

final class ReviewCheck {
    private static int passed;

    public static void main(String[] args) {
        Map<String, Document> documents = Map.of(
                "mine", new Document("mine", "tenant-a", "own payload"),
                "mine2", new Document("mine2", "tenant-a", "second own payload"),
                "foreign", new Document("foreign", "tenant-b", "foreign payload"));
        Components components = new Components(documents::get);
        InteractiveDownload interactive = new InteractiveDownload(components);
        ScheduledExportJob scheduled = new ScheduledExportJob(components);
        User user = new User("tenant-a");

        equal("interactive own tenant", "own payload", interactive.download(user, "mine"));
        forbidden("interactive foreign tenant", () -> interactive.download(user, "foreign"));
        equal("scheduled own tenant", List.of("own payload", "second own payload"),
                scheduled.run(user, List.of("mine", "mine2")));
        forbidden("scheduled foreign tenant", () -> scheduled.run(user, List.of("foreign")));
        forbidden("scheduled own then foreign", () -> scheduled.run(user, List.of("mine", "foreign")));
        forbidden("scheduled foreign then own", () -> scheduled.run(user, List.of("foreign", "mine")));
        equal("scheduled empty list", List.of(), scheduled.run(user, List.of()));
        System.out.println("Passed " + passed + " checks");
    }

    private static void equal(String name, Object expected, Object actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError(name + ": expected " + expected + ", got " + actual);
        }
        pass(name);
    }

    private static void forbidden(String name, Runnable action) {
        try {
            action.run();
        } catch (Forbidden expected) {
            pass(name);
            return;
        }
        throw new AssertionError(name + ": expected Forbidden");
    }

    private static void pass(String name) {
        passed++;
        System.out.println("PASS: " + name);
    }
}

